const templatePatterns=Object.keys(hi).filter(key=>key.includes('{{')).map(key=>{
 const names=[];let source='',last=0;
 for(const match of key.matchAll(/\{\{(\w+)\}\}/g)){source+=key.slice(last,match.index).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(.*?)';names.push(match[1]);last=match.index+match[0].length;}
 source+=key.slice(last).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 return {key,names,regex:new RegExp('^'+source+'$')};
});
export function translate(value,variables={},language='en'){
 if(typeof value!=='string')return value;
 let key=value,vars=variables;
 if(language==='hi'&&!Object.hasOwn(hi,key)){
  for(const pattern of templatePatterns){const match=pattern.regex.exec(value);if(match){key=pattern.key;vars=Object.fromEntries(pattern.names.map((name,index)=>[name,match[index+1]]));break;}}
 }
 const text=language==='hi'&&Object.hasOwn(hi,key)?hi[key]:key;
 return text.replace(/\{\{(\w+)\}\}/g,(_,name)=>String(vars[name]??''));
}
